package com.example.shortener.feature.user.service;
import com.example.shortener.common.exception.BusinessException; import com.example.shortener.feature.user.dto.RegisterForm; import com.example.shortener.feature.user.entity.*; import com.example.shortener.feature.user.repository.UserRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.UUID;
@Service public class UserService { private final UserRepository repo; private final PasswordEncoder encoder; public UserService(UserRepository repo,PasswordEncoder encoder){this.repo=repo;this.encoder=encoder;} @Transactional public User register(RegisterForm f){if(repo.existsByUsername(f.getUsername()))throw new BusinessException("Username already taken"); if(repo.existsByEmail(f.getEmail()))throw new BusinessException("Email already registered"); User u=new User(f.getUsername(),f.getEmail(),encoder.encode(f.getPassword())); UserProfile p=new UserProfile(UUID.randomUUID().toString()); p.setUser(u);u.setProfile(p);return repo.save(u);} public User findByUsername(String n){return repo.findByUsername(n).orElseThrow(()->new BusinessException("User not found"));}}
